const PGX_BOOTSTRAP_STATUS="/data/user/0/com.nianticlabs.pokemongo/files/pgexplorations/root-on-demand-bootstrap.json";
// Only fixed bootstrap state and numeric progress are persisted. Never store a
// native exception's message, stack, parameters, account identity or file paths.
// A quarantine's detail holds at most the exception's type name and an Eevx error
// code (lowercase hyphenated words), never free text.
let pgxState = "unbound";
let pgxFailure = "";
let pgxAttemptId = "";
let pgxEvidence = {};
let pgxWriteFailures = 0;
function pgxDelay(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }
function pgxPublish(state, failure = "", evidence, detail = "") {
  pgxState = state;
  pgxFailure = failure;
  if (evidence) pgxEvidence = evidence;
  let file;
  try {
    file = new File(PGX_BOOTSTRAP_STATUS, "w");
    file.write(JSON.stringify({ schemaVersion: 2, state, failure, ...(detail ? { detail } : {}),
      attemptId: pgxAttemptId, evidence: pgxEvidence,
      statusWriteFailures: pgxWriteFailures, processId: Process.id, updatedAt: Date.now() }));
    file.flush();
  } catch { pgxWriteFailures++; }
  finally { if (file) try { file.close(); } catch { pgxWriteFailures++; } }
}
function pgxSafeBootstrapFailure(error) {
  // An unexpected exception or hostile message getter cannot leak evidence or
  // replace the original startup exception.
  try {
    const message = error && error.message;
    if (["on-demand-bootstrap-stopped", "on-demand-engine-timeout",
      "on-demand-resident-init-missing", "on-demand-init-mode", "on-demand-init-process",
      "on-demand-init-stage", "on-demand-init-fields", "on-demand-enhanced-resident-missing"].includes(message)) return message;
  } catch { }
  return "on-demand-bootstrap-error";
}
// What threw, without its text: "TypeError", or "Error:enhanced-observations-frame-owner-unavailable" for an
// Eevx error code. The generic on-demand-bootstrap-error said nothing about a resident init that kept failing
// (Q4 2026-10-31 13:09 JST).
function pgxSafeBootstrapDetail(error) {
  try {
    const name = error && error.constructor && error.constructor.name;
    const kind = typeof name === "string" && /^[A-Z][A-Za-z]{0,39}Error$/.test(name) ? name : "Error";
    const message = error && error.message;
    const code = typeof message === "string" && message.length <= 80 &&
      /^[a-z][a-z0-9]*(?:-[a-z0-9]+){1,11}$/.test(message) ? message : "";
    return code ? kind + ":" + code : kind;
  } catch { return ""; }
}

// Library presence is not runtime readiness. Do not invoke an IL2CPP export
// until this exact mapping has remained present throughout the settle window.
// Unity maps libil2cpp.so long before il2cpp_init runs when the game is not in
// front, so the settle window alone is not proof either. il2cpp_get_corlib only
// reads il2cpp_defaults.corlib, which Runtime::Init sets after it creates the
// domain. il2cpp_domain_get is not a probe: before il2cpp_init it allocates and
// publishes a domain from an uninitialized runtime (access violation), and the
// game later aborts inside il2cpp_init. Call it only once corlib is present.
// The Alternative injector attaches only after the game has loaded libNianticLabsPlugin.so
// from managed code, so IL2CPP is already running; it passes settleMs 0. The corlib and
// domain checks below still gate every IL2CPP call.
async function pgxAwaitEngine(settleMs = 8000) {
  let prior = "";
  let seenAt = 0;
  const startedAt = Date.now();
  const deadline = startedAt + 90000;
  let polls = 0;
  let mappingChanges = 0;
  let domainObserved = false;
  let lastEvidenceAt = -Infinity;
  // A sampled before/after pair exposes a blocked native call without writing
  // a status file on every 250 ms poll. Diagnostics never change readiness.
  function evidence(checkpoint, force = false) {
    const now = Date.now();
    if (!force && now - lastEvidenceAt < 5000) return false;
    lastEvidenceAt = now;
    try {
      pgxPublish(pgxState, "", { checkpoint, polls, mappingChanges,
        wallElapsedMs: Math.max(0, now - startedAt) });
    } catch { /* Evidence failure must not interrupt startup. */ }
    return true;
  }
  while (Date.now() < deadline) {
    if (pgxState === "stopped") throw new Error("on-demand-bootstrap-stopped");
    polls++;
    const module = Process.findModuleByName("libil2cpp.so");
    if (module === null) {
      prior = "";
      seenAt = 0;
      domainObserved = false;
      evidence("library-missing");
    } else {
      const identity = module.base + ":" + module.size;
      if (identity !== prior) {
        prior = identity;
        seenAt = Date.now();
        mappingChanges++;
        domainObserved = false;
        pgxPublish("engine-settling");
        evidence("mapping-settle", true);
      } else if (Date.now() - seenAt >= settleMs) {
        const domainAddress = module.findExportByName("il2cpp_domain_get");
        const corlibAddress = module.findExportByName("il2cpp_get_corlib");
        if (domainAddress !== null && corlibAddress !== null) {
          const sampled = evidence("corlib-call-entered");
          const corlib = new NativeFunction(corlibAddress, "pointer", [])();
          if (sampled) evidence(corlib.isNull() ? "corlib-not-ready" : "corlib-ready", true);
          if (!corlib.isNull()) {
            const domainSample = sampled || !domainObserved;
            domainObserved = true;
            if (domainSample) evidence("domain-call-entered", true);
            const domain = new NativeFunction(domainAddress, "pointer", [])();
            if (domainSample || !domain.isNull())
              evidence(domain.isNull() ? "domain-not-ready" : "engine-ready", true);
            if (!domain.isNull()) return;
          }
        } else evidence("exports-missing");
      }
    }
    await pgxDelay(250);
  }
  evidence("engine-deadline", true);
  throw new Error("on-demand-engine-timeout");
}

// Shared on-demand bootstrap init. Used by both entry points: the injector RPC
// entry (bootstrap-init.js, called remotely with -P parameters) and the Gadget
// self-start entry (bootstrap-gadget.js, which reads its parameters from a file).
// Keep the strict identity validation here so neither entry can weaken it.
async function pgxBootstrapInit(stage, parameters) {
  if (pgxState !== "unbound") throw new Error("on-demand-bootstrap-bound");
  pgxAttemptId = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(
    parameters.startupAttemptId || "") ? parameters.startupAttemptId : "";
  // Bootstrap evidence is separate from the resident's strict identity schema.
  // Do not widen its accepted fields or weaken its ownership validation.
  const residentParameters = { ...parameters };
  delete residentParameters.startupAttemptId;
  delete residentParameters.alternativeInjector;
  pgxPublish("awaiting-il2cpp");
  try {
    if (stage !== "early" && stage !== "late") throw new Error("on-demand-init-stage");
    const keys = ["schemaVersion", "backend", "releaseId", "runNonce", "processId", "accountRunId",
      "agentVersion", "agentSha256", "agentSize", "injectorVersion", "injectorSha256", "injectorSize", "catalogDigest"];
    if (parameters.schemaVersion === 2) keys.push("runtimeMode", "processStart", "sessionAccountId");
    else if (parameters.schemaVersion !== 1) throw new Error("on-demand-init-mode");
    const actualKeys = Object.keys(residentParameters).sort();
    keys.sort();
    if (keys.length !== actualKeys.length || keys.some((key, index) => key !== actualKeys[index])) {
      throw new Error("on-demand-init-fields");
    }
    const mode = parameters.schemaVersion === 1 ? "scenario" : parameters.runtimeMode;
    if (mode !== "scenario" && mode !== "enhanced_play") throw new Error("on-demand-init-mode");
    if (parameters.schemaVersion === 2) {
      let stat;
      try {
        stat = new File("/proc/self/stat", "r");
        // QuickJS File.readText() without a size seeks to EOF to size the read.
        // procfs reports a zero file size; read a bounded buffer instead.
        const text = stat.readText(4096);
        if (text.length >= 4096) throw new Error("on-demand-init-process");
        const end = text.lastIndexOf(")");
        const start = end < 0 ? "" : text.slice(end + 1).trim().split(/\s+/)[19];
        if (parameters.processId !== Process.id || !/^[1-9][0-9]{0,19}$/.test(start || "") ||
            parameters.processStart !== start) throw new Error("on-demand-init-process");
      } finally { if (stat) stat.close(); }
    }
    await pgxAwaitEngine(parameters.alternativeInjector === true ? 0 : 8000);
    pgxPublish("evaluating-resident");
    if (mode === "enhanced_play") {
      if (typeof PGX_ENHANCED_RESIDENT !== "string") throw new Error("on-demand-enhanced-resident-missing");
      (0, eval)(PGX_ENHANCED_RESIDENT);
    } else {
      (0, eval)(PGX_RESIDENT);
    }
    const api = rpc.exports;
    if (api === undefined || typeof api.init !== "function")
      throw new Error("on-demand-resident-init-missing");
    pgxPublish("resident-evaluated");
    const result = await api.init(stage, residentParameters);
    pgxPublish("resident-bound");
    return result;
  } catch (error) {
    pgxPublish("quarantined", pgxSafeBootstrapFailure(error), undefined, pgxSafeBootstrapDetail(error));
    throw error;
  }
}

// Injector entry point. The packaged injector attaches and calls rpc.exports.init
// remotely with the controller's -P parameters. The shared bootstrap lives in
// bootstrap-core.js (pgxBootstrapInit) so the Gadget self-start path reuses the
// exact same identity validation.
rpc.exports = {
  async init(stage, parameters) { return pgxBootstrapInit(stage, parameters); },
  status() { return { schemaVersion: 1, state: pgxState, failure: pgxFailure }; },
  stop() { pgxState = "stopped"; return { ok: true, state: pgxState }; }
};

